"""The VJ's pads (native/pads.py): a new project's starter bank; the grid kept whole (a control off it or on another's
cells dropped from a hand-edited file); placing, resizing, a grid made smaller, a bank copied with new ids; what each
kind of control does to a target - a trigger, a toggle and a hold on a knob, a fader's travel through its range and
upside down, deck C's flash held, deck C in and out, a look and a preset put on a deck - and what shows lit."""
# AI: below section was generated by an AI
import os
import sys
import tempfile
import time

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np

from native import geometry, pads, vj, vj_looks

fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


class Eng:
    def __init__(self, g):
        self.rows, self.cols = g.h, g.w
        self.fft = np.zeros(16, np.uint8)
        self.last_audio = (40.0, 0)
        self.fx = {"sx": 128, "ix": 128, "c1": 0, "c2": 0, "c3": 0, "o1": 0}


class Proj:
    def __init__(self, g):
        self.options = {"sequence": {"steps": [], "bpm": 120}}
        self.geometry = g
        self.path = tempfile.mkdtemp()

    def save(self):
        pass


class App:
    def __init__(self, g):
        self.eng, self.project = Eng(g), Proj(g)


app = App(geometry.Geometry("cube", B=16))
o = vj.options(app)

# --- the layout -----------------------------------------------------------------------------------------------
st = pads.state(app.project)
b = pads.current(st)
check(len(st["banks"]) == 1 and b["cols"] == 4 and b["rows"] == 4 and len(b["controls"]) == 10,
      "a new project's pads: one starter bank of ten controls on a 4 x 4 grid")
ids = [c["id"] for c in b["controls"]]
check(len(set(ids)) == len(ids), "every control its own id")
check(all(pads.fits(b, c) for c in b["controls"]), "the starter's controls on the grid, none over another")
fader = next(c for c in b["controls"] if c["target"].get("kind") == "vj_fader")
check(pads.at(b, 2, 3) is fader and pads.at(b, 2, 0) is fader, "a 1 x 4 fader found from any of its cells")

proj2 = Proj(geometry.Geometry("cube", B=16))
proj2.options["pads"] = {"bank": 7, "banks": [{"name": "x", "cols": 99, "rows": 1, "controls": [
    {"type": "trigger", "x": 0, "y": 0}, {"type": "trigger", "x": 0, "y": 0}, {"type": "trigger", "x": 9, "y": 0},
    {"type": "laser", "x": 1, "y": 1}, "junk"]}]}
st2 = pads.state(proj2)
b2 = st2["banks"][0]
check(b2["cols"] == pads.GRID_MAX and b2["rows"] == pads.GRID_MIN and st2["bank"] == 0,
      "a hand-edited file's grid and bank brought into range")
check(len(b2["controls"]) == 1 and b2["controls"][0]["x"] == 0 and "label" in b2["controls"][0],
      "a control on another's cell, off the grid, of no known type or not a control dropped; the rest filled in")

new = pads.new_control(st, "trigger", 0, 0)
check(not pads.fits(b, new), "a control on a taken cell does not fit")
shuffle_a = pads.at(b, 0, 0)
check(not pads.place(b, shuffle_a, 1, 0) and (shuffle_a["x"], shuffle_a["y"]) == (0, 0),
      "moved onto another control: refused, left where it was")
b["controls"].remove(pads.at(b, 1, 0))
check(pads.place(b, shuffle_a, 0, 0, 2, 1) and shuffle_a["w"] == 2, "resized into a freed cell")
check(not pads.place(b, shuffle_a, 0, 0, 5, 1), "resized off the grid: refused")
check(not pads.resize_grid(b, 3, 4) and b["cols"] == 4, "the grid not made smaller under a control")
check(pads.resize_grid(b, 6, 5) and (b["cols"], b["rows"]) == (6, 5), "the grid made larger")
j = pads.copy_bank(st, 0)
check(j == 1 and len(st["banks"]) == 2 and st["banks"][1]["name"].endswith("copy"), "a bank copied after itself")
check(not ({c["id"] for c in st["banks"][0]["controls"]} & {c["id"] for c in st["banks"][1]["controls"]}),
      "the copy's controls given new ids")

# --- what the controls do -----------------------------------------------------------------------------------
check(pads.kind_of({"kind": "vj_cut"}) == "switch" and pads.kind_of({"kind": "vj_air"}) == "flip"
      and pads.kind_of({"kind": "vj_knob", "deck": 0, "key": "hue"}) == "value"
      and pads.kind_of({"kind": "pad_look"}) == "look", "targets sorted into switches, flips, values and the pads' own")

hue = {"kind": "vj_knob", "deck": 0, "key": "hue"}
st3 = {"next_id": 100}
knob = pads.new_control(st3, "knob", 0, 0, target=hue)
pads.press(app, knob)
pads.drag(app, knob, 0.25)
check(abs(vj.knob_get(app, 0, "hue") - 0.25) < 1e-3, "a knob dragged sets its target")
check(abs(pads.position(app, knob) - 0.25) < 1e-3, "and shows where the target is")
pads.release(app, knob)
fd = pads.new_control(st3, "fader", 0, 0, target=hue)
fd.update(lo=0.2, hi=0.6, invert=True)
pads.drag(app, fd, 0.0)
check(abs(vj.knob_get(app, 0, "hue") - 0.6) < 1e-3, "a fader upside down: its bottom is the top of its range")
pads.drag(app, fd, 1.0)
check(abs(vj.knob_get(app, 0, "hue") - 0.2) < 1e-3 and abs(pads.position(app, fd) - 1.0) < 1e-3,
      "its top the range's bottom, shown at the top")

vj.knob_set(app, 0, "hue", 0.3)
hold = pads.new_control(st3, "hold", 0, 0, target=hue)
hold["hi"] = 0.9
pads.press(app, hold)
held = vj.knob_get(app, 0, "hue")
lit_held = pads.lit(app, hold)
pads.release(app, hold)
check(abs(held - 0.9) < 1e-3 and lit_held, "a hold on a knob: its 'to' while held, lit")
check(abs(vj.knob_get(app, 0, "hue") - 0.3) < 1e-3 and not pads.lit(app, hold), "let go: back where it was, unlit")

tog = pads.new_control(st3, "toggle", 0, 0, target=hue)
pads.press(app, tog); pads.release(app, tog)
check(abs(vj.knob_get(app, 0, "hue") - 1.0) < 1e-3 and pads.lit(app, tog), "a toggle: on to its 'to', lit")
pads.press(app, tog); pads.release(app, tog)
check(abs(vj.knob_get(app, 0, "hue")) < 1e-3 and not pads.lit(app, tog), "pressed again: off to its 'from', unlit")

trig = pads.new_control(st3, "trigger", 0, 0, target=hue)
trig["hi"] = 0.5
pads.press(app, trig); pads.release(app, trig)
check(abs(vj.knob_get(app, 0, "hue") - 0.5) < 1e-3 and pads.lit(app, trig), "a trigger sets its value, lit a moment")
time.sleep(pads.FLASH_MS + 0.05)
check(not pads.lit(app, trig), "then unlit")

o["decks"][2]["level"] = 0.0
o["quant"] = "now"
flash = pads.new_control(st3, "hold", 0, 0, target={"kind": "vj_c_flash"})
pads.press(app, flash)
up = vj.c_level(app)
pads.release(app, flash)
check(up == float(o["c_up"]) and vj.c_level(app) == 0.0, "deck C's flash held: in at once, out at once on release")

ctog = pads.new_control(st3, "toggle", 0, 0, target={"kind": "vj_c_toggle"})
o["c_fade"] = 0.0
pads.press(app, ctog); pads.release(app, ctog)
check(vj.c_is_in(app) and pads.lit(app, ctog), "deck C in by a toggle, lit while it is in")
pads.press(app, ctog); pads.release(app, ctog)
check(not vj.c_is_in(app) and not pads.lit(app, ctog), "and out again, unlit")

look = next(n for n in vj_looks.LOOKS if n != o["decks"][1]["look"])
lp = pads.new_control(st3, "trigger", 0, 0, target={"kind": "pad_look", "deck": 1, "look": look})
pads.press(app, lp); pads.release(app, lp)
check(o["decks"][1]["look"] == look, "a look pad puts its look on its deck")
gone = pads.new_control(st3, "trigger", 0, 0, target={"kind": "pad_look", "deck": 1, "look": "no such look"})
pads.press(app, gone); pads.release(app, gone)
check(o["decks"][1]["look"] == look, "a look that is gone: nothing changes")

o["decks"][0]["hue"] = 0.77
vj.save_preset(app, 0, "warm")
o["decks"][2]["hue"] = 0.1
pp = pads.new_control(st3, "trigger", 0, 0, target={"kind": "pad_preset", "deck": 2, "name": "warm"})
pads.press(app, pp); pads.release(app, pp)
check(abs(o["decks"][2]["hue"] - 0.77) < 1e-6, "a preset pad loads the saved preset onto its deck")

empty = pads.new_control(st3, "trigger", 0, 0)
pads.press(app, empty); pads.release(app, empty)
check(not pads._rt(app)["held"] and not pads.lit(app, empty), "a control with no action yet does nothing, holds nothing")

vj.knob_set(app, 0, "hue", 0.0)
pads.press(app, hold)
app.project.options["pads"] = {"banks": [{"controls": [hold]}]}
pads.let_go(app)
check(not pads._rt(app)["held"] and abs(vj.knob_get(app, 0, "hue")) < 1e-3,
      "let go of everything (the window closed mid-press): nothing held, a hold's value put back")

# --- XY and pressure pads, release, staging (phase 2) ---------------------------------------------------------
old = {"next_id": 1, "banks": [{"controls": [{"type": "trigger", "x": 0, "y": 0}]}]}
proj3 = Proj(geometry.Geometry("cube", B=16))
proj3.options["pads"] = old
c_old = pads.state(proj3)["banks"][0]["controls"][0]
check(c_old["release"] == "snap" and c_old["target_y"] == {} and c_old["stage"] is False,
      "a control saved before XY pads gets their fields")

vj.knob_set(app, 0, "hue", 0.2)
vj.knob_set(app, 0, "kaleido", 0.0)
vj.knob_set(app, 0, "speed", 0.25)
xy = pads.new_control(st3, "xy", 0, 0, 2, 2, target=hue)
xy["target_y"] = {"kind": "vj_knob", "deck": 0, "key": "kaleido"}
xy.update(lo_y=0.0, hi_y=0.5)
check([a for a, _ in pads.surface_targets(xy)] == ["x", "y"], "an XY pad drives across and up and down")
pads.press(app, xy, xy=(0.75, 1.0))
check(abs(vj.knob_get(app, 0, "hue") - 0.75) < 1e-3 and vj.options(app)["decks"][0]["kaleido"] == 6,
      "touched: across sets one target, up and down the other through its range")
pads.move(app, xy, 0.5, 0.0)
check(abs(vj.knob_get(app, 0, "hue") - 0.5) < 1e-3 and vj.options(app)["decks"][0]["kaleido"] == 0
      and pads.where(app, xy)[:2] == (0.5, 0.0) and pads.lit(app, xy), "moved: both follow, the dot where the finger is")
pads.release(app, xy)
check(abs(vj.knob_get(app, 0, "hue") - 0.2) < 1e-3 and vj.options(app)["decks"][0]["kaleido"] == 0
      and pads.where(app, xy) is None, "let go (snap back): both back where they were before the touch")
xy["release"] = "stay"
pads.press(app, xy, xy=(0.9, 0.5))
pads.release(app, xy)
check(abs(vj.knob_get(app, 0, "hue") - 0.9) < 1e-3 and pads.where(app, xy) is not None,
      "let go (stay): left where the finger left them, the dot kept there")

pr = pads.new_control(st3, "pressure", 0, 0, 2, 2, target=hue)
pr["target_p"] = {"kind": "vj_knob", "deck": 0, "key": "speed"}
pr["hi_p"] = 0.5
check([a for a, _ in pads.surface_targets(pr)] == ["x", "p"], "a pressure pad drives across and pressure (up and down unset)")
s0 = vj.knob_get(app, 0, "speed")
pads.press(app, pr, xy=(0.1, 0.1), pressure=0.8)
check(abs(vj.knob_get(app, 0, "speed") - 0.4) < 1e-3, "its pressure through the pressure range")
pads.release(app, pr)
check(abs(vj.knob_get(app, 0, "speed") - s0) < 1e-3, "and snapped back")
xy["target"] = {"kind": "vj_cut"}
check([a for a, _ in pads.surface_targets(xy)] == ["y"], "a switch on an XY axis is not driven")

o["fader"] = 0.0
o["c_fade"] = 0.0
look2 = next(n for n in vj_looks.LOOKS if n not in (o["decks"][0]["look"], o["decks"][1]["look"]))
deck_a = o["decks"][0]["look"]
sp = pads.new_control(st3, "trigger", 0, 0, target={"kind": "pad_look", "deck": 0, "look": look2})
sp["stage"] = True
pads.press(app, sp); pads.release(app, sp)
check(o["decks"][1]["look"] == look2 and o["decks"][0]["look"] == deck_a and o["fader"] == 0.0,
      "staged with A on air: the look goes onto B, off the air, its own deck A untouched")
check(pads.staged(app, sp) == 1, "the pad knows it is staged on B")
blink = set()
for _ in range(12):
    blink.add(pads.lit(app, sp))
    time.sleep(0.05)
check(blink == {True, False}, "a staged pad blinks")
cut = pads.new_control(st3, "trigger", 0, 0, target={"kind": "vj_cut"})
pads.press(app, cut); pads.release(app, cut)
check(o["fader"] == 1.0 and pads.staged(app, sp) is None, "GO (a Cut) puts B on air; the pad stops blinking")
vj.save_preset(app, 1, "cool")
pp2 = pads.new_control(st3, "trigger", 0, 0, target={"kind": "pad_preset", "deck": 1, "name": "cool"})
pp2["stage"] = True
o["decks"][0]["hue"] = 0.0
