from native import midi_ui
midi_ui_targets = midi_ui.targets
midi_ui.targets = lambda app: [(app.eng.meta[app.eng.idx]["labels"][0], {"kind": "fx", "key": "sx"}),
                               ("VJ: cut to the other deck", {"kind": "vj_cut"}),
                               ("VJ A: Hue", {"kind": "vj_knob", "deck": 0, "key": "hue"})]
check(pads_ui.target_label(app2, fxc) == "Speed" and pads_ui.target_label(app2, {"kind": "vj_cut"})
      == "VJ: cut to the other deck" and pads_ui.target_label(app2, {"kind": "nothing_known"}) == "nothing_known",
      "a target's label from the table (one not there: its kind)")
app2.eng.idx = 1
check(pads_ui.target_label(app2, fxc) == "Rate", "another effect: the list made again, its slider's own name")
midi_ui.targets = midi_ui_targets
d1 = pads_ui._drawn(app2, 70.0, 70.0, 6)
check(d1 == pads_ui._drawn(app2, 70.0, 70.0, 6), "nothing changed: the grid not drawn again")
o2["fader"] = 0.2
pads.press(app2, hv)
d2 = pads_ui._drawn(app2, 70.0, 70.0, 6)
pads.release(app2, hv)
check(d2 != d1 and pads_ui._drawn(app2, 70.0, 70.0, 6) == d1, "a press: drawn again lit; let go: as it was")
check(pads_ui._drawn(app2, 80.0, 70.0, 6) != d1, "the window resized: drawn again")

# --- a label typed: saved once the typing stops, not at each key --------------------------------------------------
saves = []
app2.project.save = lambda: saves.append(1)
app2._pads_sel = hv["id"]
for k in ("H", "Ho", "Hol", "Hold!"):
    pads_ui._ctl_set(app2, "label", k, typed=True)
t_typed = app2._pads_typed[0]
pads_ui._flush(app2, t_typed + 0.1)
check(hv["label"] == "Hold!" and not saves, "typing: the label changes at each key, nothing saved yet")
pads_ui._flush(app2, t_typed + pads_ui.SAVE_AFTER_S + 0.01)
pads_ui._flush(app2, t_typed + pads_ui.SAVE_AFTER_S + 1.0)
check(len(saves) == 1, "the typing stopped: saved once")
pads_ui._ctl_set(app2, "label", "Hold", typed=True)
pads_ui._flush(app2)
check(len(saves) == 2, "the window closing: what was typed saved at once")
app2._pads_sel = None
pads.press(app2, hv)
pads.press(app2, hv)
pads.let_go(app2)
check(not pads._rt(app2)["held"] and abs(o2["fader"] - 0.2) < 1e-6, "all let go at once (a bank switched): however many held it")

# --- the bank shown is not an edit: no undo of its own, and an undo leaves it be ----------------------------------
from native import project as project_mod
app3 = App(geometry.Geometry("cube", B=16))
app3.project = project_mod.Project(tempfile.mkdtemp())
st5 = pads_ui._st(app3)
st5["banks"].append(pads.new_bank("Two"))
app3.project.save()
pads_ui.switch_bank(app3, 1)
pads_ui.switch_bank(app3, 0)
pads_ui.switch_bank(app3, 1)
app3.project.save()
pads_ui._undo(app3)
st5 = pads_ui._st(app3)
check(len(st5["banks"]) == 1 and st5["bank"] == 0, "Undo takes back the added bank, not the bank switches")
st5["banks"].append(pads.new_bank("Two"))
app3.project.save()
pads_ui.switch_bank(app3, 1)
st5["banks"][1]["name"] = "Renamed"
app3.project.save()
pads_ui._undo(app3)
st5 = pads_ui._st(app3)
check(st5["banks"][1]["name"] == "Two" and st5["bank"] == 1, "an undo of an edit: the bank shown stays where it is")

# --- a modulator's settings on the pads: a fader turns its rate, a toggle switches it, a trigger restarts its wave ----
from native import modulate


class Gp:
    graph, file = None, None


app3.eng.meta, app3.eng.idx, app3.gp = [{"labels": ["Speed", "Intensity"]}], 0, Gp()
mod = modulate.add(app3, key="sx", period=4)
st6 = pads_ui._st(app3)
rate_f = pads.new_control(st6, "fader", 0, 0, target={"kind": "mod", "id": mod["id"], "key": "rate"})
onoff = pads.new_control(st6, "toggle", 1, 0, target={"kind": "mod_on", "id": mod["id"]})
check(abs(pads.position(app3, rate_f) - 3 / 7) < 1e-6, "the fader shows the rate: 4 beats, along the beats")
pads.press(app3, rate_f, 1.0)
pads.release(app3, rate_f)
check(mod["period"] == 0.25, "the fader to the top: the fastest synced rate")
check(pads.kind_of(onoff["target"]) == "flip" and pads.lit(app3, onoff), "on or off a flip, lit while it runs")
pads.press(app3, onoff)
pads.release(app3, onoff)
check(mod["on"] is False and not pads.lit(app3, onoff), "the toggle switches it off, and goes dark")
labs = [lab for lab, _ in pads_ui.labels(app3)]
check(any(lab.endswith(": restart its wave") for lab in labs), "the modulator's targets in the pads' list")
modulate.add_key(app3, 0)
check(pads_ui.target_label(app3, rate_f["target"]).endswith("+ 1): rate"), "a slider added to it: the labels made again")

# --- a wave attached from the pad editor: the fader shows where the slider is set, the band it swings over ------------
from native import clock
clock.hold()
try:
    app3.eng.push = lambda: None
    modulate.modulators(app3).clear()
    modulate.apply(app3)
    b6 = pads.current(st6)
    cell = pads_ui._free_cell(b6)
    sp = pads.new_control(st6, "fader", cell[0], cell[1], target={"kind": "fx", "key": "sx"})
    b6["controls"].append(sp)
    app3.eng.fx["sx"] = 128
    app3._pads_sel, app3._pads_axis = sp["id"], "x"
    pads_ui._attach(app3)
    on = modulate.on_key(app3, "sx")
    check(len(on) == 1 and on[0]["keys"] == ["sx"] and on[0].get("sync", True), "+ LFO: a synced wave on what the fader drives")
    m = on[0]
    m.update(shape="square", depth=100)
    modulate.apply(app3)
    check(app3.eng.fx["sx"] == 178 and abs(pads.position(app3, sp) - 128 / 255) < 1e-6,
          f"the slider swung, the fader still where it was set ({app3.eng.fx['sx']}, {pads.position(app3, sp):.3f})")
    a_, b_, n_ = pads.swing(app3, sp)
    check(abs(a_ - 78 / 255) < 1e-6 and abs(b_ - 178 / 255) < 1e-6 and abs(n_ - 178 / 255) < 1e-6,
          f"the band 78..178 of 255, the wave at its top ({a_ * 255:.1f}, {b_ * 255:.1f}, {n_ * 255:.1f})")
    sp["invert"] = True
    a_, b_, n_ = pads.swing(app3, sp)
    check(abs(a_ - 77 / 255) < 1e-6 and abs(b_ - 177 / 255) < 1e-6 and abs(n_ - 77 / 255) < 1e-6, "upside down: the band too")
    sp["invert"] = False
    n = len(b6["controls"])
    pads_ui._mod_pad(app3, m["id"], "knob", "mod", "rate")
    kn = b6["controls"][-1]
    check(len(b6["controls"]) == n + 1 and kn["type"] == "knob" and kn["target"] == {"kind": "mod", "id": m["id"], "key": "rate"}
          and pads.fits(b6, kn) and app3._pads_sel == kn["id"], "rate knob: a knob on its rate in a free cell, selected")
    pads_ui._detach(app3, m["id"], "sx")
    modulate.apply(app3)
    check(not modulate.modulators(app3) and app3.eng.fx["sx"] == 128 and pads.swing(app3, sp) is None,
          "x: the wave taken off, the slider back where it was set, no band")

    # a pad that plays it: a hold pad holds the gate, a toggle latches it, MIDI's note-off lets go
    env = modulate.add(app3, key="sx", kind="env", depth=80, attack=0.01, release=0.01)
    pp = pads.new_control(st6, "hold", 0, 0, target={"kind": "mod_gate", "id": env["id"]})
    tg = pads.new_control(st6, "toggle", 1, 0, target={"kind": "mod_gate", "id": env["id"]})
    check(pads.kind_of(pp["target"]) == "gate" and not pads_ui._fits_type("fader", pp["target"])
          and pads_ui._fits_type("trigger", pp["target"]), "play: a pad's, not a fader's")
    pads.press(app3, pp)
    check(modulate.gated(app3, env["id"]) and pads.lit(app3, pp), "a hold pad down: played, lit")
    pads.press(app3, tg)
    pads.release(app3, tg)
    pads.release(app3, pp)
    check(modulate.gated(app3, env["id"]) and pads.lit(app3, tg), "a toggle latched it: still played with the hold pad up")
    pads.press(app3, tg)
    pads.release(app3, tg)
    check(not modulate.gated(app3, env["id"]) and not pads.lit(app3, pp), "the toggle again: let go, dark")
    from native import midi, midi_ui
    t = {"kind": "mod_gate", "id": env["id"]}
    check(midi.fires(t, ("note", 0, 60), 0, 100) and midi.fires(t, ("note", 0, 60), 100, 0), "MIDI: a note's press and its note-off both reach it")
    midi_ui.apply_target(app3, t, 100, 127.0, ("note", 0, 60))
    check(modulate.gated(app3, env["id"]), "a note down: played")
    midi_ui.apply_target(app3, t, 0, 127.0, ("note", 0, 60))
    check(not modulate.gated(app3, env["id"]), "its note-off: let go")
    check(pads_ui.target_label(app3, t).endswith("play (while held)"), "its label")
    pads_ui._mod_pad(app3, env["id"], "hold", "mod_gate", None)
    pl = b6["controls"][-1]
    check(pl["type"] == "hold" and pl["target"] == t and pl["label"] == f"Mod {env['id']} play", "play pad: a hold pad on it, in a free cell")
    modulate.modulators(app3).clear()
    modulate.apply(app3)
finally:
    clock.release()

# a hand-edited pads file: put right, not failing every frame (pads_hw.poll reads it each one)
class Bare:
    def __init__(self, pads_):
        self.options = {"pads": pads_}


for what, bad in (("a bank not a dict", {"banks": [3]}), ("a null grid", {"banks": [{"cols": None, "rows": "x"}]}),
                  ("a null bank", {"bank": None}), ("a position as text", {"banks": [{"controls": [
                      {"type": "trigger", "x": "1", "y": 0, "w": 1.0, "h": 1}]}]}),
                  ("controls not a list", {"banks": [{"controls": {"a": 1}}]}), ("hw a list", {"hw": []}),
                  ("a short learn", {"banks": [{"controls": [{"type": "trigger", "x": 0, "y": 0, "midi": ["note"]}]}]}),
                  ("pads not a dict", [])):
    try:
        st_ = pads.state(Bare(bad))
        from native import pads_hw as ph
        ph.hw(st_)
        ph.wanted(App(geometry.Geometry("cube", B=16)), st_)
        check(isinstance(st_["banks"][0], dict), f"{what}: read")
    except Exception as e:
        check(False, f"{what}: {type(e).__name__} {e}")
st_ = pads.state(Bare({"banks": [{"controls": [{"type": "trigger", "x": 0, "y": 0, "id": 5},
                                               {"type": "trigger", "x": 1, "y": 0, "id": 5}]}]}))
ids = [c["id"] for c in st_["banks"][0]["controls"]]
check(len(set(ids)) == 2 and st_["next_id"] > max(ids), f"an id given twice, no next_id: each its own ({ids})")

# a bank switched (the phone, the controller) while Edit drags a control: the drag let go, not laid on the other grid
app4 = App(geometry.Geometry("cube", B=16))
pads_ui._fill_banks = pads_ui._fill_side = lambda a: None
st4 = pads_ui._st(app4)
st4["banks"].append(pads.new_bank("Big", 8, 8))
b0 = st4["banks"][0]
c0 = pads.at(b0, 0, 0)
app4._pads_edit = True
app4._pads_drag = ("move", c0["id"], (0, 0), (c0["x"], c0["y"]))
pads_ui.switch_bank(app4, 1)
pads_ui._dragging(app4, app4._pads_drag, 6 * 50 + 10, 5 * 50 + 10, 0, 0, 50, 50, 6, pads.current(st4))
check((c0["x"], c0["y"]) == (0, 0) and pads.fits(b0, c0) and app4._pads_drag is None,
      f"a move across a bank switch: the control left where it was ({c0['x']}, {c0['y']})")
dpg.destroy_context()

print("pads:", "FAILED" if fails else "ok")
sys.exit(1 if fails else 0)
